    int shortestMatchingSubstring(std::string s, std::string p) {
        size_t star1 = p.find('*');
        size_t star2 = p.find('*', star1 + 1);
        std::string a = p.substr(0, star1);
        std::string b = p.substr(star1 + 1, star2 - star1 - 1);
        std::string c = p.substr(star2 + 1);

        std::vector<int> posA = findAll(s, a);
        std::vector<int> posB = findAll(s, b);
        std::vector<int> posC = findAll(s, c);

        if (posA.empty() || posB.empty() || posC.empty()) return -1;

        int lenA = a.length(), lenB = b.length(), lenC = c.length();
        int ans = INT_MAX;

        for (int startB : posB) {
            int endB = startB + lenB;
            auto itA = std::upper_bound(posA.begin(), posA.end(), startB - lenA);
            if (itA == posA.begin()) continue;
            --itA;
            int startA = *itA;

            auto itC = std::lower_bound(posC.begin(), posC.end(), endB);
            if (itC == posC.end()) continue;
            int startC = *itC;
            int endC = startC + lenC;

            ans = std::min(ans, endC - startA);
        }
        return ans == INT_MAX ? -1 : ans;
    }
