import java.util.*;

class Solution {
    private List<Integer> findAll(String s, String sub) {
        List<Integer> matches = new ArrayList<>();
        if (sub.isEmpty()) {
            for (int i = 0; i <= s.length(); i++) matches.add(i);
            return matches;
        }
        int[] pi = new int[sub.length()];
        for (int i = 1; i < sub.length(); i++) {
            int j = pi[i - 1];
            while (j > 0 && sub.charAt(i) != sub.charAt(j)) j = pi[j - 1];
            if (sub.charAt(i) == sub.charAt(j)) j++;
            pi[i] = j;
        }
        int j = 0;
        for (int i = 0; i < s.length(); i++) {
            while (j > 0 && s.charAt(i) != sub.charAt(j)) j = pi[j - 1];
            if (s.charAt(i) == sub.charAt(j)) j++;
            if (j == sub.length()) {
                matches.add(i - sub.length() + 1);
                j = pi[j - 1];
            }
        }
        return matches;
    }

    public int shortestMatchingSubstring(String s, String p) {
        int star1 = p.indexOf('*');
        int star2 = p.indexOf('*', star1 + 1);
        String a = p.substring(0, star1);
        String b = p.substring(star1 + 1, star2);
        String c = p.substring(star2 + 1);

        List<Integer> posA = findAll(s, a);
        List<Integer> posB = findAll(s, b);
        List<Integer> posC = findAll(s, c);

        if (posA.isEmpty() || posB.isEmpty() || posC.isEmpty()) return -1;

        int lenA = a.length(), lenB = b.length(), lenC = c.length();
        int ans = Integer.MAX_VALUE;

        for (int startB : posB) {
            int endB = startB + lenB;
            int targetA = startB - lenA;
            int idxA = Collections.binarySearch(posA, targetA);
            if (idxA < 0) idxA = -idxA - 2;
            if (idxA < 0) continue;
            int startA = posA.get(idxA);

            int idxC = Collections.binarySearch(posC, endB);
            if (idxC < 0) idxC = -idxC - 1;
            if (idxC >= posC.size()) continue;
            int startC = posC.get(idxC);
            int endC = startC + lenC;

            ans = Math.min(ans, endC - startA);
        }
        return ans == Integer.MAX_VALUE ? -1 : ans;
    }
}

var shortestMatchingSubstring = function(s, p) {
    const star1 = p.indexOf('*');
    const star2 = p.indexOf('*', star1 + 1);
    const a = p.slice(0, star1);
    const b = p.slice(star1 + 1, star2);
    const c = p.slice(star2 + 1);

    function findAll(sub) {
        if (!sub) {
            const res = [];
            for (let i = 0; i <= s.length; i++) res.push(i);
            return res;
        }
        const pi = new Int32Array(sub.length);
        for (let i = 1; i < sub.length; i++) {
            let j = pi[i - 1];
            while (j > 0 && sub[i] !== sub[j]) j = pi[j - 1];
            if (sub[i] === sub[j]) j++;
            pi[i] = j;
        }
        const matches = [];
        let j = 0;
        for (let i = 0; i < s.length; i++) {
            while (j > 0 && s[i] !== sub[j]) j = pi[j - 1];
            if (s[i] === sub[j]) j++;
            if (j === sub.length) {
                matches.push(i - sub.length + 1);
                j = pi[j - 1];
            }
        }
        return matches;
    }

    const posA = findAll(a);
    const posB = findAll(b);
    const posC = findAll(c);

    if (!posA.length || !posB.length || !posC.length) return -1;

    const lenA = a.length, lenB = b.length, lenC = c.length;
    let ans = Infinity;

    function bisectRight(arr, x) {
        let l = 0, r = arr.length;
        while (l < r) {
            const m = (l + r) >> 1;
            if (arr[m] <= x) l = m + 1;
            else r = m;
        }
        return l;
    }

    function bisectLeft(arr, x) {
        let l = 0, r = arr.length;
        while (l < r) {
            const m = (l + r) >> 1;
            if (arr[m] < x) l = m + 1;
            else r = m;
        }
        return l;
    }

    for (const startB of posB) {
        const endB = startB + lenB;
        const idxA = bisectRight(posA, startB - lenA) - 1;
        if (idxA < 0) continue;
        const startA = posA[idxA];

        const idxC = bisectLeft(posC, endB);
        if (idxC >= posC.length) continue;
        const startC = posC[idxC];
        const endC = startC + lenC;

        if (endC - startA < ans) ans = endC - startA;
    }

    return ans === Infinity ? -1 : ans;
};
